# Each NOW() of the operation was replaced with "2026-01-15T09:00:00Z"^^<http://www.w3.org/2001/XMLSchema#dateTime>, the step's cst:transactionTime. The engine reads no clock.
PREFIX  xsd:  <http://www.w3.org/2001/XMLSchema#>
PREFIX  pat:  <https://www.nebularis.org/neuro-semantic/lattice/persistence-store#>

DELETE {
  GRAPH <urn:g:facilities> {
    <https://example.org/lending#facility-1> <https://example.org/lending#margin> 3.25 .
  }
  GRAPH <urn:g:meta/6> {
    <https://example.org/lending#facility-1> pat:epoch ?rowEpoch .
    <https://example.org/lending#facility-1> pat:seq "1"^^xsd:long .
    <https://example.org/lending#facility-1> pat:head ?prevRev .
  }
}
INSERT {
  GRAPH <urn:g:facilities> {
    <https://example.org/lending#facility-1> <https://example.org/lending#margin> 3.5 .
  }
  GRAPH ?addGraph {
    <https://example.org/lending#facility-1> <https://example.org/lending#margin> 3.5 .
  }
  GRAPH ?delGraph {
    <https://example.org/lending#facility-1> <https://example.org/lending#margin> 3.25 .
  }
  GRAPH <urn:g:meta/6> {
    <https://example.org/lending#facility-1> pat:epoch "1"^^xsd:long .
    <https://example.org/lending#facility-1> pat:seq "2"^^xsd:long .
    <https://example.org/lending#facility-1> pat:head <urn:rev:facility-1/2> .
  }
  GRAPH <urn:g:txn> {
    <urn:txn:facility-1-2> pat:rev <urn:rev:facility-1/2> .
    <urn:txn:facility-1-2> pat:requestDigest "01c0d2273ac8d68d6672f54e4a1ef0fc5a7cd625708b404c5578cdc899cd6521" .
  }
  GRAPH ?logGraph2 {
    <urn:rev:facility-1/2> <http://www.w3.org/1999/02/22-rdf-syntax-ns#type> pat:Revision .
    <urn:rev:facility-1/2> pat:target <https://example.org/lending#facility-1> .
    <urn:rev:facility-1/2> pat:epoch "1"^^xsd:long .
    <urn:rev:facility-1/2> pat:seq "2"^^xsd:long .
    <urn:rev:facility-1/2> pat:prevRev ?prevRev .
    <urn:rev:facility-1/2> pat:txn ?txnKey .
    <urn:rev:facility-1/2> pat:recordedAt ?now .
    <urn:rev:facility-1/2> pat:asserts ?addGraph .
    <urn:rev:facility-1/2> pat:retracts ?delGraph .
  }
}
WHERE
  { { FILTER ( ( ( ( ( ( isIRI(<https://example.org/lending#facility-1>) && ( datatype("1"^^xsd:long) = datatype("0"^^xsd:long) ) ) && ( datatype("1"^^xsd:long) = datatype("0"^^xsd:long) ) ) && ( datatype("2"^^xsd:long) = datatype("0"^^xsd:long) ) ) && isIRI(<urn:rev:facility-1/2>) ) && isIRI(<urn:txn:facility-1-2>) ) && ( datatype("01c0d2273ac8d68d6672f54e4a1ef0fc5a7cd625708b404c5578cdc899cd6521") = xsd:string ) ) }
    BIND(IRI(concat(str(<urn:g:txlog/>), substr(str("2026-01-15T09:00:00Z"^^xsd:dateTime), 1, 7))) AS ?logGraph)
    BIND(?logGraph AS ?logGraph2)
    BIND(IRI(concat(str(<urn:rev:facility-1/2>), "/add")) AS ?addGraph)
    BIND(IRI(concat(str(<urn:rev:facility-1/2>), "/del")) AS ?delGraph)
    GRAPH <urn:g:dataset>
      { <urn:g:dataset>
                  pat:epoch  "1"^^xsd:long
      }
    GRAPH <urn:g:meta/6>
      { <https://example.org/lending#facility-1>
                  pat:epoch  ?rowEpoch ;
                  pat:seq    "1"^^xsd:long
        OPTIONAL
          { <https://example.org/lending#facility-1>
                      pat:head  ?prevRev
          }
        FILTER NOT EXISTS { GRAPH <urn:g:meta/6>
                              { <https://example.org/lending#facility-1>
                                          pat:deleted  true
                              }
                          }
      }
    FILTER NOT EXISTS { GRAPH <urn:g:txn>
                          { <urn:txn:facility-1-2>
                                      pat:rev  ?any
                          }
                      }
    BIND(str(<urn:txn:facility-1-2>) AS ?txnKey)
    BIND("2026-01-15T09:00:00Z"^^xsd:dateTime AS ?now)
  }

